      sha256 "7c6554f08740d96c32bd347f87da0c1c71e07b872b4e7dd909b790b060909b1f"
    end
    on_intel do
      url "https://github.com/crowdin/crowdin-cli/releases/download/5.1.0/crowdin-darwin-x64"
