    end
  end
  on_linux do
    on_arm do
      url "https://github.com/crowdin/crowdin-cli/releases/download/5.1.0/crowdin-linux-arm64"
      sha256 "a90283123908a1e2b31a645a98251b92610f30ecfbd3e54542a8bdd240f2ce9c"
    end
    on_intel do
